package gost3412128_test

import (
	"crypto/cipher"
	"fmt"

	"gitverse.ru/uzer_007/gogost/v3/gost3412128"
)

func Example() {
	key := []byte{
		0x88, 0x99, 0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff,
		0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77,
		0xfe, 0xdc, 0xba, 0x98, 0x76, 0x54, 0x32, 0x10,
		0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef,
	}
	plaintext := []byte{
		0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x00,
		0xff, 0xee, 0xdd, 0xcc, 0xbb, 0xaa, 0x99, 0x88,
	}

	block := gost3412128.NewCipher(key)
	var _ cipher.Block = block

	ciphertext := make([]byte, gost3412128.BlockSize)
	block.Encrypt(ciphertext, plaintext)

	fmt.Printf("%x\n", ciphertext)
	// Output: 7f679d90bebc24305a468d42b9d4edcd
}
